/// <summary>
/// MPJ_24248 Pricing Data Extract
/// Process Price Change tracking records for Discounts and create Price Data Feed records
/// </summary>
using System.ComponentModel.Composition;

[Export(identifierStr(Dynamics.AX.Application.METPriceChangeTrack))]
[ExportMetadata(enumStr(METPriceChangeType), enumLiteralStr(METPriceChangeType, DiscountEnabled))]
public class METPriceChangeTrackDiscountEnabled extends METPriceChangeTrack
{
    container   discountTypesCon;

}

Method.Source:
/// <summary>
/// Set internal variables
/// </summary>
/// <param name = "_priceChangeTracking">Price change tracking record</param>
public void setInternals(METPriceChangeTracking _priceChangeTracking, boolean _showValidation)
{
    super(_priceChangeTracking, _showValidation);
    discountTypesCon = [RetailDiscountOfferTypeBase::Multibuy, RetailDiscountOfferTypeBase::DiscountOffer];
}

/// <summary>
/// Get the Price change type
/// </summary>
/// <returns>Price change type</returns>
public METPriceChangeType getPriceChangeType()
{
    return METPriceChangeType::DiscountEnabled;
}

    /// <summary>
    /// Process the Change tracking record and create a Price data feed record
    /// </summary>
    public void process()
    {
        RetailPeriodicDiscountLine  retailPeriodicDiscountLine;
        Query               custPreviewQuery;
        Query               productPreviewQuery;
        GUPPricingRuleCopy  pricingRuleCopyCustHeader, pricingRuleCopy;
        InventSiteId        inventSiteId;
        Set                 custAccountSet, inventItemSet;
        GUPGroupAll         discountTableGroup;

        priceDataFeedCount = 0;
        priceDataFeedList = new RecordInsertList(tableNum(METPriceDataFeed));

        discountTableGroup = RetailPeriodicDiscount::find(priceChangeTrackingOrig.RefRecId).HeaderPricingGroupCode;

        pricingRuleCopyCustHeader.initFromPricingRule(GUPPricingRule::find(priceChangeTrackingOrig.pricingRuleHeader));
        
        while select OfferId, LinePricingRule, UnitOfMeasure, InventDimId, LineNum
            from    retailPeriodicDiscountLine
            where   retailPeriodicDiscountLine.OfferId == priceChangeTrackingOrig.DiscountCode
        {
            pricingRuleCopy.initFromPricingRule(GUPPricingRule::find(retailPeriodicDiscountLine.LinePricingRule));
        
            inventSiteId = InventDim::find(retailPeriodicDiscountLine.InventDimId).InventSiteId;

            custPreviewQuery = this.buildCustQuery(pricingRuleCopyCustHeader, InventSiteId, discountTableGroup);
            custAccountSet = this.buildCustValues(custPreviewQuery, pricingRuleCopyCustHeader);
            
            productPreviewQuery = this.buildProductQueryBase(pricingRuleCopy);
            inventItemSet = this.buildItemValues(productPreviewQuery, pricingRuleCopy);

            if(custAccountSet && inventItemSet)
            {
                this.processMulti(custAccountSet, inventItemSet, retailPeriodicDiscountLine);
            }
        }

        if(priceDataFeedCount)
        {
            ttsbegin;
            priceDataFeedList.insertDatabase();
            ttscommit;
        }
    }

    /// <summary>
    /// Process the Change tracking record
    /// </summary>
    /// <param name = "_custAccountSet">Customer Accounts</param>
    /// <param name = "_inventItemSet">Items</param>
    /// <param name = "_retailPeriodicDiscountLine">Discount line</param>
    public void processMulti(Set _custAccountSet, Set _inventItemSet, RetailPeriodicDiscountLine _retailPeriodicDiscountLine)
    {
        METPriceChangeTracking priceChangeTrackingUpdate;
        SetEnumerator       custAccountEnumerator, inventItemEnumerator;
        AccountNum          custAccount;
        ItemId              inventItem;
        InventSiteId        inventSiteId;
        Set                 custAccountSet, inventItemSet;
        boolean             validityCheck;
        METUnitOfMeasure    unitOfMeasure;

        custAccountSet  = _custAccountSet;
        inventItemSet   = _inventItemSet;

        inventSiteId = InventDim::find(_retailPeriodicDiscountLine.InventDimId).InventSiteId;
        unitOfMeasure = UnitOfMeasure::find(_retailPeriodicDiscountLine.UnitOfMeasure).Symbol;

        custAccountEnumerator = custAccountSet.getEnumerator();

        while(custAccountEnumerator.moveNext())
        {
            custAccount = custAccountEnumerator.current();

            inventItemEnumerator = inventItemSet.getEnumerator();

            while(inventItemEnumerator.moveNext())
            {
                validityCheck = true;
                inventItem  = inventItemEnumerator.current();
                
                //1. Is there an Entry in Price Feed previously for Item number, Customer, Site, Unit of measure, From date, From quantity
                if(!METPriceDataFeed::existForCustItem(custAccount, inventItem, inventSiteId, unitOfMeasure, priceChangeTrackingOrig.FromDate, priceChangeTrackingOrig.QuantityAmountFrom))
                {
                    //2.Execute the Item/Site validity check
                    validityCheck = this.ItemSiteValidation(inventItem, inventSiteId);

                    //3. Execute the Customer/Item validity check
                    validityCheck = validityCheck && this.CustomerItemValidation(custAccount, inventItem);
                                            
                    if(validityCheck)
                    {
                        //update priceChangeTracking values for processing, but dont committ to DB
                        buf2Buf(priceChangeTrackingOrig, priceChangeTrackingUpdate);
                        
                        priceChangeTrackingUpdate.PriceDiscAccountRelation = custAccount;
                        priceChangeTrackingUpdate.ItemId                  = inventItem;
                        priceChangeTrackingUpdate.InventSiteId            = inventSiteId;
                        priceChangeTrackingUpdate.UnitId                  = unitOfMeasure;

                        this.createPriceDataFeed(priceChangeTrackingUpdate, _retailPeriodicDiscountLine);
                        this.createRelatedComponents(priceChangeTrackingUpdate);
                        this.createPriceDataFeedExpire(priceChangeTrackingUpdate, _retailPeriodicDiscountLine);
                        
                    }
                }
            }
        }
    }

    /// <summary>
    /// Create a Price data feed record
    /// </summary>
    /// <param name = "_priceChangeTracking">Price change tracking</param>
    /// <param name = "_retailPeriodicDiscountLine">Discount line</param>
    public void createPriceDataFeed(METPriceChangeTracking _priceChangeTracking, RetailPeriodicDiscountLine  _retailPeriodicDiscountLine)
    {
        this.createPriceDataFeedBase(_priceChangeTracking);

        priceDataFeed.ChangeCode        = _priceChangeTracking.DiscountCode;
        priceDataFeed.ChangeCodeLineNum = _retailPeriodicDiscountLine.LineNum;
        priceDataFeed.CreationType      = METCreationType::Original;

        priceDataFeedList.add(priceDataFeed);
        priceDataFeedCount++;
    }

    /// <summary>
    /// Create a Price data feed record
    /// </summary>
    /// <param name = "_priceChangeTracking">Price change tracking</param>
    /// <param name = "_retailPeriodicDiscountLine">Discount line</param>
    public void createPriceDataFeedRelated(METPriceChangeTracking _priceChangeTracking, RetailPeriodicDiscountLine  _retailPeriodicDiscountLine)
    {
        this.createPriceDataFeedBase(_priceChangeTracking);

        priceDataFeed.ChangeCode        = _priceChangeTracking.DiscountCode;
        priceDataFeed.ChangeCodeLineNum = _retailPeriodicDiscountLine.LineNum;
        priceDataFeed.CreationType      = METCreationType::RelatedDiscount;

        priceDataFeedList.add(priceDataFeed);
        priceDataFeedCount++;
    }

    /// <summary>
    /// Create a Price data feed record
    /// </summary>
    /// <param name = "_priceChangeTracking">Price change tracking</param>
    /// <param name = "_retailPeriodicDiscountLine">Discount line</param>
    public void createPriceDataFeedExpire(METPriceChangeTracking _priceChangeTracking, RetailPeriodicDiscountLine  _retailPeriodicDiscountLine)
    {
        METPriceChangeTracking priceChangeTrackingUpdate;
        TransDate   expireDate;

        expireDate = this.getExpireDate(_priceChangeTracking.ToDate);

        if(!METPriceDataFeed::existForCustItem(_priceChangeTracking.PriceDiscAccountRelation,
                                                _priceChangeTracking.ItemId,
                                                _priceChangeTracking.InventSiteId,
                                                _priceChangeTracking.UnitId,
                                                expireDate,
                                                _priceChangeTracking.QuantityAmountFrom))
        {
            buf2Buf(_priceChangeTracking, priceChangeTrackingUpdate);

            priceChangeTrackingUpdate.FromDate = expireDate;

            this.createPriceDataFeedBase(priceChangeTrackingUpdate);

            priceDataFeed.ChangeCode        = priceChangeTrackingUpdate.DiscountCode;
            priceDataFeed.ChangeCodeLineNum = _retailPeriodicDiscountLine.LineNum;
            priceDataFeed.CreationType      = METCreationType::ExpiryDiscount;

            priceDataFeedList.add(priceDataFeed);
            priceDataFeedCount++;  
        }
    }

    /// <summary>
    /// Create a Price data feed records from Related components
    /// </summary>
    /// <param name = "_priceChangeTracking">Price change tracking</param>
    public void createRelatedComponents(METPriceChangeTracking _priceChangeTracking)
    {
        METPriceChangeTracking      priceChangeTrackingUpdate;
        RetailPeriodicDiscount      retailPeriodicDiscount;
        RetailPeriodicDiscountLine  retailPeriodicDiscountLine;
        InventDim                   inventDim;
        RefRecId                    pricingRuleHeaderPrevious, pricingRuleHeader, linePricingRulePrevious, linePricingRule;
        Query                       custPreviewQuery;
        Query                       productPreviewQuery;
        GUPPricingRuleCopy          pricingRuleCopyCustHeader, pricingRuleCopy;
        Set                         custAccountSet, inventItemSet;
        TransDate                   startDate;
        QueryBuildDataSource        qbds;
        QueryBuildRange             qbr;

        while select OfferId, HeaderPricingRule, ValidFrom, HeaderPricingGroupCode
            from    retailPeriodicDiscount
            where   retailPeriodicDiscount.OfferId      != _priceChangeTracking.DiscountCode
            &&      retailPeriodicDiscount.ValidTo      > _priceChangeTracking.FromDate
            &&      retailPeriodicDiscount.PeriodicDiscountType in discountTypesCon
            &&      retailPeriodicDiscount.Status       == RetailDisabledEnabled::Enabled
            &&      retailPeriodicDiscount.IsGUPDiscount == NoYes::Yes
        join LinePricingRule, LineNum
            from    retailPeriodicDiscountLine
            where   retailPeriodicDiscountLine.OfferId  == retailPeriodicDiscount.OfferId
        exists join InventDim
            where   InventDim.InventDimId               == retailPeriodicDiscountLine.InventDimId
            &&      InventDim.InventSiteId              == _priceChangeTracking.InventSiteId
        {
            pricingRuleHeader   = retailPeriodicDiscount.HeaderPricingRule;
            linePricingRule     = retailPeriodicDiscountLine.LinePricingRule;

            if(pricingRuleHeader != pricingRuleHeaderPrevious)
            {
                pricingRuleCopyCustHeader.initFromPricingRule(GUPPricingRule::find(pricingRuleHeader));
                custPreviewQuery = this.buildCustQuery(pricingRuleCopyCustHeader, _priceChangeTracking.InventSiteId, retailPeriodicDiscount.HeaderPricingGroupCode);
                
                //filter by the Customer
                qbds = custPreviewQuery.dataSourceTable(tableNum(CustTable));
                if(qbds)
                {
                    qbr = SysQuery::findOrCreateRange(qbds, fieldNum(CustTable, AccountNum));
                    qbr.value(queryValue(_priceChangeTracking.PriceDiscAccountRelation));
                }
                
                custAccountSet = this.buildCustValues(custPreviewQuery, pricingRuleCopyCustHeader);
            }
            
            if(LinePricingRule != LinePricingRulePrevious)
            {
                pricingRuleCopy.initFromPricingRule(GUPPricingRule::find(linePricingRule));
                productPreviewQuery = this.buildProductQueryBase(pricingRuleCopy);
                
                //filter by the Item
                qbds = productPreviewQuery.dataSourceTable(tableNum(InventTable));
                if(qbds)
                {
                    qbr = SysQuery::findOrCreateRange(qbds, fieldNum(InventTable, ItemId));
                    qbr.value(queryValue(_priceChangeTracking.ItemId));
                }

                inventItemSet = this.buildItemValues(productPreviewQuery, pricingRuleCopy);
            }
            
            if(inventItemSet.in(_priceChangeTracking.ItemId) && custAccountSet.in(_priceChangeTracking.PriceDiscAccountRelation))
            {
                startDate  = retailPeriodicDiscount.ValidFrom ?  retailPeriodicDiscount.ValidFrom : todayDate;

                if(!METPriceDataFeed::existForCustItem(_priceChangeTracking.PriceDiscAccountRelation, 
                                                        _priceChangeTracking.ItemId, 
                                                        _priceChangeTracking.InventSiteId, 
                                                        _priceChangeTracking.UnitId, 
                                                        startDate,
                                                        _priceChangeTracking.QuantityAmountFrom))
                {
                    buf2Buf(_priceChangeTracking, priceChangeTrackingUpdate);
                    //update priceChangeTracking values for processing, but dont committ to DB
                    priceChangeTrackingUpdate.FromDate = startDate;
                    this.createPriceDataFeedRelated(priceChangeTrackingUpdate, retailPeriodicDiscountLine);
                }
            }

            pricingRuleHeaderPrevious = pricingRuleHeader;
            linePricingRulePrevious = linePricingRule;
        }
    }
